var sensors = ['middle', 'head'];
var messages = [];

// Iterate over the predefined sensor order
for (var i = 0; i < sensors.length; i++) {
    var sensor = sensors[i];

    // Check if the current sensor is present in the payload
    if (msg.payload.hasOwnProperty(sensor)) {
        // Create a message for the current sensor
        var message = {
            topic: msg.topic + '/' + sensor, // Append sensor name to the topic
            payload: msg.payload[sensor], // Set temperature as payload
            timestamp: msg.payload.time, // Include timestamp in the message
            fault: msg.payload.fault === true
        };

        // Add the message to the array
        messages.push(message);
    } else {
        // If the sensor is not present, add a null message to the array
        messages.push(null);
    }
}

// Return the array of messages
return messages;

